package com.littlebuddy.v2

import java.io.File
import java.security.KeyStore
import java.util.concurrent.TimeUnit

/** Per-test synthetic identity, generated by the same JDK used by Gradle. Never a production asset. */
internal object LoopbackTlsFixture {
    fun create(directory: File): KeyStore {
        check(directory.isDirectory)
        val store = File(directory, "loopback.p12")
        check(!store.exists())
        val executable = if (System.getProperty("os.name").startsWith("Windows")) "keytool.exe" else "keytool"
        val keytool = File(System.getProperty("java.home"), "bin/$executable")
        check(keytool.isFile) { "Test JDK keytool unavailable" }
        val process = ProcessBuilder(keytool.absolutePath,
            "-genkeypair", "-noprompt", "-alias", "loopback", "-keyalg", "RSA", "-keysize", "2048",
            "-validity", "1", "-dname", "CN=loopback-fixture", "-ext", "SAN=IP:127.0.0.1",
            "-storetype", "PKCS12", "-keystore", store.absolutePath,
            "-storepass", "fixture", "-keypass", "fixture")
            .redirectErrorStream(true)
            .redirectOutput(File(directory, "keytool-output.txt")).start()
        try {
            check(process.waitFor(20, TimeUnit.SECONDS)) { "TLS fixture generation timed out" }
            check(process.exitValue() == 0) { "TLS fixture generation failed" }
        } finally {
            if (process.isAlive) {
                process.destroyForcibly()
                check(process.waitFor(5, TimeUnit.SECONDS)) { "TLS fixture generator did not terminate" }
            }
        }
        return KeyStore.getInstance("PKCS12").apply {
            store.inputStream().use { load(it, "fixture".toCharArray()) }
        }
    }
}
